-- Datos de DEMOSTRACIÓN para la página "Zonas críticas" (clustering K-Means).
-- 38 incidencias con ubicación en La Molina, concentradas en 4 focos.
--
-- Cargar (con la app detenida), desde la raíz del repositorio:
--   sqlite3 alerta_vecinal.db < ML/zonasCriticas/datos_demo.sql
--
-- Borrarlas después:
--   sqlite3 alerta_vecinal.db "DELETE FROM Incidencias WHERE Descripcion LIKE '%[datos de demostración]';"
--   (su historial se borra en cascada)
--
-- Se insertan directo en SQLite: si usas Algolia, presiona "Sincronizar todas las incidencias" en el Dashboard.
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;
COMMIT;
